 $isDispatcher=($ctx['user_role']==='organization_admin')||organizationHasPermission($pdo,$ctx,'dispatch.dispatch_assignments.update');$hasMission=($ctx['user_role']==='organization_admin')||organizationHasPermission($pdo,$ctx,'dispatch.mission_status.update');
 if(!$isDispatcher&&!$hasMission)throw new RuntimeException('You do not have permission to update mission status.');
