 $trans=['assigned'=>['acknowledged'],'acknowledged'=>['responding'],'responding'=>['on_scene'],'on_scene'=>['transporting','completed'],'transporting'=>['completed']];$old=$m['assignment_status'];if(!in_array($next,$trans[$old]??[],true))throw new RuntimeException('That mission transition is not allowed from the current status.');
 if($old==='transporting'&&$next==='completed'){ $handoff=$pdo->prepare("SELECT 1 FROM patient_handoffs WHERE dispatch_assignment_id=? AND status='completed' LIMIT 1"); $handoff->execute([$id]); if(!$handoff->fetchColumn()) throw new RuntimeException('Complete the receiving-facility handoff before closing a transporting mission.'); }
 $timeCols=['acknowledged'=>'acknowledged_at','responding'=>'departed_at','on_scene'=>'arrived_at','completed'=>'completed_at'];$sets=['assignment_status=?'];$params=[$next];if(isset($timeCols[$next])){$sets[]=$timeCols[$next].'=NOW()';}$params[]=$id;$pdo->prepare('UPDATE dispatch_assignments SET '.implode(',',$sets).' WHERE id=?')->execute($params);
 $requestSets=['status=?'];$rp=[$next];$reqTime=['acknowledged'=>'acknowledged_at','on_scene'=>'arrived_at','transporting'=>'transport_started_at','completed'=>'completed_at'];if(isset($reqTime[$next]))$requestSets[]=$reqTime[$next].'=NOW()';$rp[]=$m['emergency_request_id'];$pdo->prepare('UPDATE emergency_requests SET '.implode(',',$requestSets).' WHERE id=?')->execute($rp);
 $ambMap=['acknowledged'=>'reserved','responding'=>'dispatched','on_scene'=>'on_scene','transporting'=>'transporting','completed'=>'returning'];$newAmb=$ambMap[$next];if($newAmb!==$m['ambulance_status']){$pdo->prepare('UPDATE ambulances SET status=? WHERE id=?')->execute([$newAmb,$m['ambulance_id']]);fleetStatusLog($pdo,(int)$m['ambulance_id'],$m['ambulance_status'],$newAmb,(int)$ctx['user_id'],'Mission '.$m['reference_number'].' → '.$next.'.');}
