 if($next==='completed'){$members=$pdo->prepare('SELECT organization_member_id FROM crew_assignments WHERE dispatch_assignment_id=?');$members->execute([$id]);$mids=array_map('intval',$members->fetchAll(PDO::FETCH_COLUMN));$pdo->prepare("UPDATE crew_assignments SET response_status='completed' WHERE dispatch_assignment_id=?")->execute([$id]);$up=$pdo->prepare("UPDATE personnel_profiles SET availability_status='available' WHERE organization_member_id=? AND availability_status='assigned'");$log=$pdo->prepare("INSERT INTO personnel_availability_logs (organization_member_id,old_status,new_status,changed_by_user_id,notes) VALUES (?,'assigned','available',?,?)");foreach($mids as $mid){$up->execute([$mid]);if($up->rowCount())$log->execute([$mid,(int)$ctx['user_id'],'Released after '.$m['reference_number'].'.']);}}
 if(!empty($m['requester_user_id'])){$titles=['acknowledged'=>'Response Team Acknowledged','responding'=>'Ambulance En Route','on_scene'=>'Responders Arrived','transporting'=>'Patient Transport Started','completed'=>'Rescue Mission Completed'];assignmentNotifyUser($pdo,(int)$m['requester_user_id'],'dispatch_update',$titles[$next],$labels[$next].' Reference: '.$m['reference_number'].'.','emergency_request',(int)$m['emergency_request_id'],'mission-status:'.$id.':'.$next);}
